
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_th_fc_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_th_fc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.943322650501638e+00, -4.848188260877194e+00, -4.713472157971140e+00, -4.524409758707577e+00, -4.262959655405701e+00, -3.910132956087606e+00, -3.452951732947789e+00, -2.899279723259558e+00, -2.299887318750813e+00, -1.751884745191830e+00, -1.271533171661349e+00, -9.296306308491583e-01, -8.429795047955173e-01, -7.289506414834541e-01, -6.016390283935433e-01, -4.951355409612941e-01, -4.178104768488677e-01, -3.315401328274903e-01, -1.144344773850197e-01, 6.771184726541242e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


